INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT156-S4-Q26$batch09$, 156, 4, 26, $batch09$Principle-Strengthen$batch09$, $batch09$Letter to the editor: In calling on antinuclear activists to “live up to their own ideals” and help find better ways of disposing of nuclear waste, advocates of nuclear power merely prove their own dishonesty. Everyone knows that antinuclear activists want the world rid of nuclear power as soon as possible, and they believe any other option is environmentally irresponsible. But finding better ways of disposing of nuclear waste would probably make nuclear power acceptable to more people and thus likelier to continue.$batch09$, $batch09$Which one of the following principles, if valid, most helps to justify the reasoning in the argument?$batch09$, $batch09$C$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$If other options are available, it is irresponsible to take a possibly beneficial course of action that has the potential of causing harm.$batch09$, $batch09$Wrong Judgment$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$It is better to eliminate a potentially harmful practice than to try to improve it, if improving it will not significantly reduce its capacity to cause harm.$batch09$, $batch09$Wrong Judgment$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$If one is calling on people to act in a way that will possibly undermine their goals, it is dishonest to ask that they do so for the sake of their ideals.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$It is irresponsible to try to induce others to find a practice acceptable if it is not one’s own belief that that practice is acceptable.$batch09$, $batch09$Wrong Judgment$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$It is dishonest to ask people to live up to their ideals without revealing whether one’s own ideals conflict with theirs.$batch09$, $batch09$Wrong Trigger$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Nuclear power advocates who call on antinuclear activists to "live up to their own ideals" by helping find better ways to dispose of nuclear waste are being dishonest.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The activists want nuclear power gone as soon as possible. Better waste disposal would probably make nuclear power more acceptable and more likely to continue.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The request is presented as serving the activists' ideals, but complying would work against the activists' goal. The conclusion calls that dishonest. The principle has to say that asking people to undermine their own goals in the name of their ideals is dishonest.$batch09$), (3, $batch09$Goal$batch09$, $batch09$It's dishonest to ask people to do something that could undermine their goals for the sake of their ideals.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is about irresponsibility. The conclusion is about dishonesty.$batch09$), ($batch09$B$batch09$, $batch09$This supports the activists' preference for eliminating nuclear power. It says nothing about the advocates being dishonest.$batch09$), ($batch09$C$batch09$, $batch09$Better waste disposal could keep nuclear power going, which undermines the activists' goal. The advocates still ask for it in the name of the activists' ideals. C calls that dishonest, which is the conclusion.$batch09$), ($batch09$D$batch09$, $batch09$This is about irresponsibility, not dishonesty. And the advocates do believe nuclear power is acceptable, so D's trigger isn't met.$batch09$), ($batch09$E$batch09$, $batch09$The advocates' ideals are no secret. The letter's complaint isn't that they hid their views. It's that the request undermines the activists' goals.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT156-S4-Q26$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
